const rows = $input.all();
if (!rows.length) return [];

const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Africa/Cairo',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(new Date());

const map = Object.fromEntries(parts.map(p => [p.type, p.value]));
const today = `${map.year}-${map.month}-${map.day}`;

const cleanDate = (v) => String(v ?? '').trim().slice(0, 10);

const candidates = rows
  .filter(i => cleanDate(i.json.Publish_Date) >= today)
  .sort((a,b) => {
    const ad = cleanDate(a.json.Publish_Date);
    const bd = cleanDate(b.json.Publish_Date);
    if (ad !== bd) return ad.localeCompare(bd);
    return Number(a.json.row_number || 0) - Number(b.json.row_number || 0);
  });

return candidates.length ? [candidates[0]] : [];

const src=$json;
const pillar=String(src.Content_Pillar||'').trim().toLowerCase();
const imageText=String(src.Image_Text||'').trim();
const post=String(src['Post Description']||'').toLowerCase();
const strategy=String(src.Strategy||'').toLowerCase();
const notes=String(src.Notes||'').toLowerCase();
const all=[pillar,imageText.toLowerCase(),strategy,notes,post].join(' ');

const presets={
  customer_experience:{
    label:'تجربة العميل',
    mood:'bright customer journey',
    palette:'warm ivory, soft sky blue, pale sand, subtle copper',
    title:'العميل يشتري التجربة',
    subhead:'العميل يتذكر الرحلة من أول ظهور حتى التسليم.',
    benefits:['رحلة أوضح','تعقيد أقل','ثقة أعلى','عودة أكثر'],
    scene:'a premium customer-experience journey metaphor from first discovery to purchase and delivery, with clear physical touchpoints connected through one elegant path, a business owner observing the journey, no labels or readable text'
  },
  customer_insight:{
    label:'فهم العميل',
    mood:'bright customer insight',
    palette:'light sand, pale teal, clean ivory, subtle copper',
    title:'راقب العميل',
    subhead:'المنافس يعطي إشارات، لكن العميل يعطي الحقيقة.',
    benefits:['سؤال أفضل','دليل أقوى','قرار أدق','تطوير أسرع'],
    scene:'a premium business insight metaphor where customer evidence is clear and central while competitor noise stays secondary in the distance, consultant or owner studying real behavior and signals, no readable text'
  },
  decision:{
    label:'قرار إداري',
    mood:'bright strategic contrast',
    palette:'warm ivory, pale blue, restrained amber, deep navy accents',
    title:'القرار قبل التنفيذ',
    subhead:'الاختيار السريع قد تكون له تكلفة طويلة.',
    benefits:['قرار أوضح','مخاطرة أقل','هدر أقل','نمو أهدأ'],
    scene:'a clear business decision metaphor with one protagonist facing two distinct strategic paths, one chaotic and costly and one structured and sustainable'
  },
  expansion:{
    label:'قرار توسع',
    mood:'bright optimistic architectural',
    palette:'clean ivory, soft sky blue, warm gold, light stone',
    title:'قبل ما تتوسع',
    subhead:'التوسع الجيد يبدأ من أساس يتحمل النمو.',
    benefits:['اختبار الطلب','حساب السيولة','جاهزية التشغيل','توسع محسوب'],
    scene:'a business expansion metaphor with a successful operation in the foreground and multiple possible expansion paths, one disciplined path leading to sustainable growth'
  },
  profitability:{
    label:'ربحية',
    mood:'bright analytical premium',
    palette:'off-white, pale steel blue, warm copper, restrained navy',
    title:'مش كل بيع مكسب',
    subhead:'ارتفاع المبيعات لا يعني بالضرورة ارتفاع الربح.',
    benefits:['هامش أقوى','تكلفة أوضح','بيع أذكى','ربح حقيقي'],
    scene:'a premium profitability metaphor where sales activity rises while profit margin is squeezed, shown through physical business objects and abstract unlabeled data shapes'
  },
  cashflow:{
    label:'سيولة',
    mood:'bright financial tension',
    palette:'light cool gray, pale mint, soft teal, warm copper',
    title:'الكاش أهم من الرقم',
    subhead:'المبيعات على الورق لا تدفع الالتزامات وحدها.',
    benefits:['تحصيل أسرع','مخزون أذكى','التزام أقل','سيولة أفضل'],
    scene:'a cash-flow metaphor with money moving through a clean business pipeline while receivables, inventory and obligations create visible bottlenecks'
  },
  pricing:{
    label:'تسعير',
    mood:'bright commercial clarity',
    palette:'warm cream, pale slate, muted gold, deep navy accents',
    title:'السعر قرار',
    subhead:'التسعير ليس رقمًا منفصلًا عن القيمة والتكلفة.',
    benefits:['قيمة أوضح','هامش أفضل','خصم أقل','قرار أسرع'],
    scene:'a refined pricing strategy metaphor using product value, cost and margin as physical balanced elements in a premium business setting'
  },
  operations:{
    label:'تشغيل',
    mood:'bright operational precision',
    palette:'off-white, soft sage, pale teal, restrained copper',
    title:'التشغيل يكشف الحقيقة',
    subhead:'النمو بدون نظام يحوّل الضغط إلى فوضى.',
    benefits:['تدفق أسرع','اختناق أقل','فريق أوضح','جودة أعلى'],
    scene:'a modern SME operations metaphor moving from recurring firefighting and bottlenecks into a clean prevention system and organized workflow, realistic business context'
  },
  diagnostic:{
    label:'تشخيص أعمال',
    mood:'bright consulting editorial',
    palette:'ivory, pale warm gray, blue-gray, subtle copper',
    title:'التشخيص قبل الحل',
    subhead:'السؤال الأدق يختصر حلولًا كثيرة خاطئة.',
    benefits:['سبب أوضح','قرار أدق','هدر أقل','خطوة عملية'],
    scene:'an editorial business diagnostic scene with a consultant and business owner studying evidence, numbers and root causes before making a decision'
  },
  personal:{
    label:'خبرة استشارية',
    mood:'bright human editorial',
    palette:'warm ivory, soft beige, light slate blue, subtle copper',
    title:'درس من الشغل',
    subhead:'الخبرة الحقيقية تبدأ من مواقف وقرارات واقعية.',
    benefits:['خبرة عملية','وجهة نظر','قرار أوضح','تعلم أسرع'],
    scene:'a premium editorial personal-brand consulting scene from a real working moment, side-profile or over-the-shoulder, no attempt to imitate a specific real person'
  }
};

let best=null;

// 1) Explicit Content_Pillar has the highest priority.
if(/تجرب/.test(pillar)) best='customer_experience';
else if(/منافس|عميل/.test(pillar)) best='customer_insight';
else if(/وقت|تشغيل|عمليات/.test(pillar)) best='operations';
else if(/توسع|نمو|فرع/.test(pillar)) best='expansion';
else if(/ربح|ربحية|مبيعات/.test(pillar)) best='profitability';
else if(/سيولة|كاش|تحصيل/.test(pillar)) best='cashflow';
else if(/تسعير|سعر/.test(pillar)) best='pricing';
else if(/قرار/.test(pillar)) best='decision';
else if(/استشار|تشخيص/.test(pillar)) best='diagnostic';

// 2) Short Image_Text is the next strongest semantic signal.
if(!best){
  const t=imageText.toLowerCase();
  if(/تجرب|عميل يشتري|رحلة/.test(t)) best='customer_experience';
  else if(/منافس|راقب العميل|فهم العميل/.test(t)) best='customer_insight';
  else if(/حرائق|وقت|تشغيل/.test(t)) best='operations';
  else if(/توسع|فرع|نمو/.test(t)) best='expansion';
  else if(/ربح|مكسب|هامش/.test(t)) best='profitability';
  else if(/كاش|سيولة|تحصيل/.test(t)) best='cashflow';
  else if(/سعر|تسعير/.test(t)) best='pricing';
  else if(/قرار|عشوائ/.test(t)) best='decision';
}

// 3) Weighted fallback on the full post.
if(!best){
  const rules={
    personal:['تعلمت','رأيي','خبرتي','من واقع','موقف','شفت','قابلت','درس','تجربتي'],
    expansion:['توسع','فرع','فروع','توسيع'],
    cashflow:['كاش','سيولة','تحصيل','مخزون','التزامات'],
    pricing:['تسعير','خصم','سعر'],
    operations:['تشغيل','اختناق','إطفاء الحرائق','يتكرر','إجراء'],
    decision:['قرار','اختيار','عشوائ','مخاطرة'],
    diagnostic:['تشخيص','سبب جذري','قبل الحل','تحليل','الخلل'],
    profitability:['ربح','ربحية','هامش','مكسب']
  };
  let score=-1;
  for(const [type,words] of Object.entries(rules)){
    const s=words.reduce((a,w)=>a+(all.includes(w)?1:0),0);
    if(s>score){score=s;best=type;}
  }
}
best=best||'diagnostic';
const p=presets[best];

// Preserve the editorial title explicitly written in the sheet whenever it is concise.
const title=(imageText && imageText.length<=45) ? imageText : p.title;

const variants=[
  'wide environmental editorial composition with a strong foreground subject and cinematic depth',
  'high-end side-angle editorial composition with one dominant metaphor and open upper space',
  'clean elevated business composition with structured visual hierarchy and a single focal point',
  'architectural symbolic composition with strong depth, central safe zone and uncluttered upper space'
];

return [{json:{
  ...src,
  Visual_Type:best,
  Visual_Label:p.label,
  Visual_Mood:p.mood,
  Palette_Direction:p.palette,
  Image_Title_Final:title,
  Visual_Subhead:p.subhead,
  B1:p.benefits[0],B2:p.benefits[1],B3:p.benefits[2],B4:p.benefits[3],
  Visual_Scene:p.scene,
  Composition_Variant:variants[Number(src.row_number||1)%variants.length],
  Strategy_Version:'V4.1'
}}];

const item=$input.first();
const candidates=[
  item.json?.result?.image,
  item.json?.image,
  item.json?.result?.response?.image,
  item.json?.data?.image
].filter(v=>typeof v==='string' && v.length>1000);
if(!candidates.length){
  throw new Error('FLUX returned no base64 image');
}
let b64=candidates[0];
if(b64.includes('base64,')) b64=b64.split('base64,').pop();
const strategy=$('Build Premium Visual Prompt').first().json;
return [{
  json:{
    ...strategy,
    Image_Model:'@cf/black-forest-labs/flux-1-schnell'
  },
  binary:{
    image:{
      data:b64,
      mimeType:'image/jpeg',
      fileName:'linkedin_base_'+String(strategy.row_number||'x')+'.jpg',
      fileExtension:'jpg'
    }
  }
}];

const strategy=$('Build Premium Visual Prompt').first().json;
const baseId=$('Upload Base Image to Drive').first().json.id;
const presentationId=$json.id;
const requests=[
  {replaceAllText:{containsText:{text:'{{CONTENT_PILLAR}}',matchCase:true},replaceText:strategy.Visual_Label}},
  {replaceAllText:{containsText:{text:'{{IMAGE_TEXT}}',matchCase:true},replaceText:strategy.Image_Title_Final}},
  {replaceAllText:{containsText:{text:'{{SUBHEAD}}',matchCase:true},replaceText:strategy.Visual_Subhead}},
  {replaceAllText:{containsText:{text:'{{B1}}',matchCase:true},replaceText:strategy.B1}},
  {replaceAllText:{containsText:{text:'{{B2}}',matchCase:true},replaceText:strategy.B2}},
  {replaceAllText:{containsText:{text:'{{B3}}',matchCase:true},replaceText:strategy.B3}},
  {replaceAllText:{containsText:{text:'{{B4}}',matchCase:true},replaceText:strategy.B4}},
  {replaceAllShapesWithImage:{
    imageUrl:'https://drive.google.com/uc?export=download&id='+baseId,
    replaceMethod:'CENTER_CROP',
    containsText:{text:'{{BASE_IMAGE}}',matchCase:true},
    pageObjectIds:['p1']
  }}
];
return [{json:{presentationId,batchPayload:{requests}}}];
